// Keeps the hand-written declaration files honest. Two checks, both made by
// the TypeScript compiler:
//
//   1. test/types/usage.ts uses the packages the way an application would,
//      under `strict`, with lines marked @ts-expect-error for the mistakes the
//      declarations must catch.
//   2. A file generated here lists what each entry point really exports at
//      run time, and the methods each class really has. The compiler then
//      refuses a name the declarations lack, and a declared name that does
//      not exist.
//   3. A second generated file holds what each resolver client method really
//      returned from a running resolver, typed as that method's declared
//      return type. The compiler refuses a member declared with the wrong
//      type and a member declared as always present that was not returned.
//
// The compiler runs with no DOM and no Node types, so the declarations must
// stand on their own.
import assert from "node:assert/strict";
import { execFile } from "node:child_process";
import { mkdir, readFile, writeFile } from "node:fs/promises";
import { createRequire } from "node:module";
import { fileURLToPath, pathToFileURL } from "node:url";
import { promisify } from "node:util";
import test from "node:test";
import { MockInvoiceAdapter } from "../../../apps/resolver/src/invoice-adapter.js";
import { createServer, InMemoryOfferStore } from "../../../apps/resolver/src/server.js";
import {
  createOfferRevocation,
  createSignedOffer,
  generateOfferKeyPair,
  signRecurrenceRequest
} from "../../protocol/src/index.js";
import { FiberOffersClient } from "../src/index.js";

const typesDirectory = fileURLToPath(new URL("./types/", import.meta.url));
const sourceDirectory = new URL("../src/", import.meta.url);
// The compiler's launcher, as its own package.json names it.
const require = createRequire(import.meta.url);
const compilerManifest = require.resolve("typescript/package.json");
const compiler = fileURLToPath(new URL(require(compilerManifest).bin.tsc, pathToFileURL(compilerManifest)));

// Every entry point the two packages publish. The React entry points import
// React, which is an optional peer and may not be installed, so their exports
// are read from the source text instead of by loading them.
const ENTRY_POINTS = [
  { specifier: "@fiber-offers/protocol", load: () => import("../../protocol/src/index.js") },
  { specifier: "@fiber-offers/sdk", load: () => import("../src/index.js") },
  { specifier: "@fiber-offers/sdk/browser", load: () => import("../src/browser.js") },
  { specifier: "@fiber-offers/sdk/node", load: () => import("../src/node.js") },
  { specifier: "@fiber-offers/sdk/react", source: "react.js" },
  { specifier: "@fiber-offers/sdk/react-native", source: "react-native.js" }
];

// How to construct each exported class, with every optional setting given, so
// the members an instance really has can be compared with the declared ones.
const fetchImpl = async () => ({ ok: true, status: 200, json: async () => ({}), text: async () => "" });
const node = { url: "http://127.0.0.1:8227", token: "token", username: "user", password: "password", fetchImpl, timeoutMs: 1000 };
const INSTANCES = {
  FiberOfferError: (Class) => new Class("message", "CODE", { field: "value" }),
  FiberOffersClient: (Class) => new Class({ resolverUrl: "https://offers.merchant.example", apiKey: "key", fetchImpl, timeoutMs: 1000 }),
  FiberRpcClient: (Class) => new Class(node),
  FiberPaymentClient: (Class) => new Class(node),
  FiberNodeDiagnosticsClient: (Class) => new Class(node),
  FiberTopologyClient: (Class) => new Class({ merchant: node, payer: node }),
  FiberPaymentFlowClient: (Class) =>
    new Class({ resolver: { checkPayment: fetchImpl, requestInvoice: fetchImpl }, payer: { sendPayment: fetchImpl } }),
  InMemoryRecurringApprovalStore: (Class) => new Class([]),
  WebStorageRecurringApprovalStore: (Class) => new Class({ storage: { getItem: () => null, setItem() {} }, key: "key" }),
  JsonFileRecurringApprovalStore: (Class) => new Class("/nonexistent/approvals.json"),
  FiberRecurringPaymentScheduler: (Class) =>
    new Class({
      paymentFlow: { payOffer: fetchImpl },
      resolver: { getOffer: fetchImpl },
      store: { list: fetchImpl, get: fetchImpl, put: fetchImpl },
      autoStart: false
    })
};

test("the declarations match what the packages export, and the usage file type-checks", async () => {
  const lines = [
    "// Generated by packages/sdk/test/types.test.js. Not committed.",
    "type Statics<T> = { [K in Exclude<keyof T, \"prototype\"> as T[K] extends (...args: any[]) => any ? K : never]: true };",
    ""
  ];
  let exportsChecked = 0;
  let classesChecked = 0;

  for (const [index, entry] of ENTRY_POINTS.entries()) {
    const local = `entry${index}`;
    lines.push(`import * as ${local} from ${JSON.stringify(entry.specifier)};`);
    const module = entry.load ? await entry.load() : undefined;
    const names = module ? Object.keys(module) : await exportedNames(new URL(entry.source, sourceDirectory));
    assert.ok(names.length > 0, `${entry.specifier} exports nothing`);
    exportsChecked += names.length;
    lines.push(`export const ${local}Exports: Record<keyof typeof ${local}, true> = ${record(names)};`);

    for (const name of module ? names : []) {
      const value = module[name];
      if (typeof value !== "function" || !/^class\b/.test(Function.prototype.toString.call(value))) continue;
      assert.ok(INSTANCES[name], `add a way to construct ${name} to INSTANCES, so its members can be checked`);
      classesChecked += 1;

      // Two questions per class. Is every method the class really has
      // declared? And does every declared member exist on an instance? The
      // second goes through a variable, so a field the declarations leave out
      // on purpose is not an error.
      const instance = INSTANCES[name](value);
      const methods = methodNames(value.prototype);
      const members = new Set([...methods, ...Object.getOwnPropertyNames(instance)]);
      const base = builtInBase(value.prototype);
      const type = `InstanceType<typeof ${local}.${name}>`;
      const declared = base === "Object" ? `keyof ${type}` : `Exclude<keyof ${type}, keyof ${base}>`;
      lines.push(
        `export const ${local}${name}Methods: { [K in keyof ${type}]?: true } = ${record(methods)};`,
        `const ${local}${name}Members = ${record(members)} as const;`,
        `export const ${local}${name}Declared: { [K in ${declared}]-?: true } = ${local}${name}Members;`,
        `export const ${local}${name}Statics: Statics<typeof ${local}.${name}> = ${record(staticNames(value))};`
      );
    }
    lines.push("");
  }
  assert.ok(exportsChecked > 100, `only ${exportsChecked} exports were found`);
  assert.ok(classesChecked > 10, `only ${classesChecked} classes were found`);

  // The browser entry point narrows the values and must still offer every type.
  const declarations = await readFile(new URL("index.d.ts", sourceDirectory), "utf8");
  const typeNames = [
    ...[...declarations.matchAll(/^export (?:interface|type) (\w+)/gm)].map((match) => match[1]),
    ...[...declarations.matchAll(/^export type \{([^}]*)\} from /gm)].flatMap((match) =>
      match[1].split(",").map((name) => name.trim()).filter(Boolean)
    )
  ];
  assert.ok(typeNames.length > 100, `only ${typeNames.length} types were found in index.d.ts`);
  lines.push(`import type { ${typeNames.join(", ")} } from "@fiber-offers/sdk/browser";`);
  lines.push(`export type BrowserTypes = [${typeNames.join(", ")}];`, "");

  await mkdir(`${typesDirectory}.generated`, { recursive: true });
  await writeFile(`${typesDirectory}.generated/exports.ts`, `${lines.join("\n")}\n`);

  const samples = await resolverClientSamples();
  const untested = [...methodNames(FiberOffersClient.prototype)].filter(
    (method) => !samples.some((sample) => sample.method === method) && !NOT_SAMPLED[method]
  );
  assert.deepEqual(untested, [], "call these FiberOffersClient methods in resolverClientSamples, or list them in NOT_SAMPLED");
  await writeFile(
    `${typesDirectory}.generated/responses.ts`,
    [
      "// Generated by packages/sdk/test/types.test.js. Not committed.",
      "// What each method returned from a running resolver, as its declared return type.",
      'import type { FiberOffersClient } from "@fiber-offers/sdk";',
      "",
      "// The declared type with every object left open to members it does not name:",
      "// a resolver may return more than the declarations promise, never less.",
      "type Open<T> = T extends readonly (infer Item)[]",
      "  ? Open<Item>[]",
      "  : T extends object",
      "    ? { [K in keyof T]: Open<T[K]> } & { [key: string]: unknown }",
      "    : T;",
      'type Returned<M extends keyof FiberOffersClient> = FiberOffersClient[M] extends (...args: any[]) => infer R ? Open<Awaited<R>> : never;',
      "",
      ...samples.map(
        (sample, index) =>
          `// ${sample.label}\nexport const sample${index}: Returned<${JSON.stringify(sample.method)}> = ${JSON.stringify(sample.value, null, 2)};\n`
      )
    ].join("\n")
  );

  const result = await promisify(execFile)(process.execPath, [compiler, "--project", typesDirectory, "--pretty", "false"]).catch(
    (error) => error
  );
  assert.equal(result.code, undefined, `the declarations and the code disagree:\n${result.stdout}${result.stderr}`);
});

// Methods of the resolver client that return nothing a resolver sent.
const NOT_SAMPLED = {
  offerQrUrl: "builds a URL",
  reconciliationCsvUrl: "builds a URL",
  getReconciliationCsv: "returns text",
  createOffer: "asks a Fiber node, not the resolver",
  createAndRegisterOfferFromNode: "asks a Fiber node first; what it registers is sampled through registerOffer",
  resolveOffer: "returns what getOffer returns",
  resolveAndRequestInvoice: "returns what getOffer and requestInvoice return"
};

// Runs the reference resolver and calls the client's methods against it,
// keeping what each returned.
async function resolverClientSamples() {
  const apiKey = "types-test-key";
  // Mock invoices, and a node that reports each one as received when asked.
  const mock = new MockInvoiceAdapter();
  const invoiceAdapter = {
    mode: "mock",
    createInvoice: (input) => mock.createInvoice(input),
    probe: () => mock.probe(),
    getNodeIdentity: () => mock.getNodeIdentity(),
    syncInvoice: async (paymentHash) => ({
      mode: "fiber-rpc",
      payment_hash: paymentHash,
      status: "invoice_received",
      fiber_status: "Received",
      get_invoice_method: "get_invoice",
      amount: "0x3e8",
      currency: "Fibt",
      raw_result: { status: "Received" }
    })
  };
  const server = createServer({
    store: new InMemoryOfferStore(),
    invoiceAdapter,
    apiKey,
    demoMode: true,
    topologyClient: false,
    workers: false,
    rateLimitMax: 0,
    allowPrivateWebhookTargets: true,
    logger: { error() {}, info() {}, warn() {} }
  });
  await new Promise((resolve) => server.listen(0, "127.0.0.1", resolve));
  const resolverUrl = `http://127.0.0.1:${server.address().port}`;
  const samples = [];
  const client = new FiberOffersClient({ resolverUrl, apiKey });
  // Calls a method and keeps the answer. `label` says which case this is.
  const call = async (method, label, ...args) => {
    const value = await client[method](...args);
    samples.push({ method, label: `${method}: ${label}`, value });
    return value;
  };

  try {
    const keys = generateOfferKeyPair();
    const subscriber = generateOfferKeyPair();
    const ckb = { asset_type: "ckb", symbol: "CKB" };
    const terms = {
      node_id: `02${"c".repeat(64)}`,
      public_key: keys.publicKeyPem,
      resolver_url: resolverUrl,
      description: "Type fixture",
      network: "testnet",
      assets: [ckb]
    };
    const offer = createSignedOffer({ ...terms, amount_min: "1000", amount_max: "5000" }, keys.privateKeyPem);
    const plan = createSignedOffer(
      { ...terms, amount_min: "2000", amount_max: "2000", recurrence: { interval: "monthly", amount: "2000", cap_cycles: 3 } },
      keys.privateKeyPem
    );

    await call("registerOffer", "a new offer with an address", offer, { username: "shop" });
    await call("registerOffer", "a recurring offer", plan);
    await call("createAndRegisterOffer", "signed here", { ...terms, description: "Signed by the client" }, keys.privateKeyPem);
    await call("demoCreateOffer", "signed by a demo resolver", { description: "Demo", amount: "1500", network: "testnet" });
    await call("getOffer", "by ID", offer.offer_id);
    await call("resolveFiberAddress", "by address", `shop@${new URL(resolverUrl).host}`);
    await call("bindFiberAddress", "a second name", "store", offer.offer_id);
    await call("listOffers", "all");
    await call("diagnostics", "of the resolver");

    await call("checkPayment", "a request that would be issued", offer, { amount: "1000", asset: ckb });
    await call("checkPayment", "a request that would be refused", offer, { amount: "1" });
    const invoice = await call("requestInvoice", "a new invoice", offer, { amount: "1000", asset: ckb }, { idempotencyKey: "order-1" });
    await call("requestInvoice", "the same request again", offer, { amount: "1000", asset: ckb }, { idempotencyKey: "order-1" });
    await call("getResolution", "an open invoice", offer, invoice.resolution_id);
    await call("getReceipt", "of an open invoice", offer, invoice.resolution_id);
    await call("syncResolution", "one resolution", offer, invoice.resolution_id);
    await call("syncResolutions", "every open resolution", offer, { includeTerminal: true });

    const webhook = await call("createWebhook", "one endpoint", offer, { url: `${resolverUrl}/demo/webhook-receiver`, events: ["invoice.paid"] });
    await call("getWebhooks", "of the offer", offer);
    await call("updateWebhook", "paused", offer, webhook.id, { disabled: true });
    await call("updateWebhook", "resumed", offer, webhook.id, { disabled: false });
    await call("rotateWebhookSecret", "a new secret", offer, webhook.id);
    await call("testWebhook", "a test event", offer, webhook.id);
    await call("updateResolutionStatus", "marked paid", offer, invoice.resolution_id, { status: "invoice_paid", source: "backoffice" });
    await call("getResolution", "a paid invoice", offer, invoice.resolution_id);
    await call("getResolutions", "of the offer", offer);
    await call("getResolutions", "one page, newest first", offer, { limit: 1, order: "desc" });
    await call("getAllResolutions", "read to the end", offer, { pageSize: 1 });
    await call("getWebhookEvents", "of the offer", offer);
    await call("getAllWebhookEvents", "read to the end", offer, { pageSize: 1 });
    await call("listOffers", "one page", { limit: 1 });
    await call("listAllOffers", "read to the end", { pageSize: 1 });
    const events = await client.getWebhookEvents(offer);
    await call("deliverWebhookEvents", "the outbox", offer, { retryFailed: true });
    await call("deliverWebhookEvent", "one event", offer, events.events[0].id, { retryFailed: true });
    await call("getReconciliation", "of the offer", offer);
    await call("deleteWebhook", "removed", offer, webhook.id);

    const cycle = signRecurrenceRequest(plan, { amount: "2000", asset: ckb, recurrence_cycle: 1 }, subscriber.privateKeyPem);
    await call("getRecurrenceStatus", "a subscription before its first cycle", plan, cycle.approval_id);
    const cycleInvoice = await call("requestInvoice", "a subscription cycle", plan, cycle);
    await call("getRecurrenceStatus", "a subscription with an open cycle", plan, cycle.approval_id);
    await call("getResolution", "a cycle", plan, cycleInvoice.resolution_id);
    await call("checkPayment", "a cycle already requested", plan, cycle);
    await call("getRecurrenceStatus", "across all subscribers", plan);
    await call("getRecurrenceStatus", "of an offer that is not recurring", offer, cycle.approval_id);

    await call("revokeOffer", "by the offer key", offer, createOfferRevocation(offer, keys.privateKeyPem, { reason: "closed" }));
    await call("getOffer", "after revocation", offer.offer_id);
  } finally {
    await new Promise((resolve) => server.close(resolve));
  }
  return samples;
}

function record(names) {
  return `{ ${[...names].sort().map((name) => `${JSON.stringify(name)}: true`).join(", ")} }`;
}

// A class's methods, its own and inherited from other classes of the package.
// Getters and setters are left out: the declarations write those as properties.
function methodNames(prototype) {
  const names = new Set();
  for (let current = prototype; current && !isBuiltIn(current.constructor); current = Object.getPrototypeOf(current)) {
    for (const [name, descriptor] of Object.entries(Object.getOwnPropertyDescriptors(current))) {
      if (name !== "constructor" && typeof descriptor.value === "function") names.add(name);
    }
  }
  return names;
}

function staticNames(constructor) {
  return Object.entries(Object.getOwnPropertyDescriptors(constructor))
    .filter(([name, descriptor]) => !["length", "name", "prototype"].includes(name) && typeof descriptor.value === "function")
    .map(([name]) => name);
}

// The built-in class a class of the package is built on: "Object", or "Error".
function builtInBase(prototype) {
  let current = prototype;
  while (current && !isBuiltIn(current.constructor)) current = Object.getPrototypeOf(current);
  return current?.constructor?.name ?? "Object";
}

function isBuiltIn(constructor) {
  return typeof constructor !== "function" || /\[native code\]/.test(Function.prototype.toString.call(constructor));
}

async function exportedNames(file) {
  const text = await readFile(file, "utf8");
  const names = new Set();
  for (const match of text.matchAll(/^export\s+(?:async\s+)?(?:function\*?|class|const|let)\s+([A-Za-z_$][\w$]*)/gm)) {
    names.add(match[1]);
  }
  for (const match of text.matchAll(/^export\s*\{([^}]*)\}/gm)) {
    for (const part of match[1].split(",")) {
      const name = part.trim().split(/\s+as\s+/).pop();
      if (name) names.add(name);
    }
  }
  assert.ok(!/^export\s+\*/m.test(text), `${file} re-exports with "export *", which this reader does not follow`);
  return [...names];
}
